info:
// Cloud Control API v2.0-beta.
// see https://shelly-api-docs.shelly.cloud/cloud-control-api/communication-v2
//
// The cloud server config node must be set to API version v2.
// v2 uses a different vocabulary than v1: on:true instead of turn:"on",
// the cover position replaces direction/pos, and all_status has no v2 equivalent.
// see doc/migration/cloud-api-v1-to-v2.md

func:
msg.payload = {
    type : 'get',
    id : 'b48a0a1cd978',

    // ask for the status; omit to get only identity and online state
    select : ['status'],
};

return msg;

// One call instead of one per device. The cloud allows 1 request/second,
// so batching is the difference between 10 seconds and 1.
msg.payload = {
    type : 'get',
    ids : ['b48a0a1cd978', 'a1b2c3d4e5f6'],
    select : ['status', 'settings'],

    // optional: trim the response to the components you care about
    // pick : { status : ['switch:0'] },
};

return msg;

msg.payload = {
    type : 'switch',
    id : 'b48a0a1cd978',
    channel : 0,
    on : true,
};

return msg;

msg.payload = {
    type : 'switch',
    id : 'b48a0a1cd978',
    channel : 0,
    on : false,
};

return msg;

// toggle_after flips back to the opposite state after n seconds.
msg.payload = {
    type : 'switch',
    id : 'b48a0a1cd978',
    channel : 0,
    on : true,
    toggle_after : 30,
};

return msg;

msg.payload = {
    type : 'cover',
    id : 'a1b2c3d4e5f6',
    channel : 0,
    position : 'open',   // open | close | stop | 0..100

    // duration is only valid with open, close or stop
    // duration : 5,
};

return msg;

msg.payload = {
    type : 'cover',
    id : 'a1b2c3d4e5f6',
    channel : 0,
    position : 80,

    // slatPosition : 40,   // 0..100, for venetian blinds
};

return msg;

// relative moves by an offset instead of to an absolute position.
// position and relative must not be combined.
msg.payload = {
    type : 'cover',
    id : 'a1b2c3d4e5f6',
    channel : 0,
    relative : -20,
};

return msg;

msg.payload = {
    type : 'light',
    id : '8caab55397c7',
    channel : 0,
    on : true,
    mode : 'white',
    temperature : 3000,   // 2700..7000
    brightness : 70,      // 0..100
};

return msg;

msg.payload = {
    type : 'light',
    id : '8caab55397c7',
    channel : 0,
    on : true,
    mode : 'color',
    red : 255,
    green : 128,
    blue : 0,
    white : 0,
    gain : 100,   // 0..100

    // effect : 3,   // 0..6
};

return msg;

// Groups replace the v1 bulk_control and cover switches, covers and lights
// in one request. Ids are "<DEVICE_ID>_<CHANNEL>".
msg.payload = {
    type : 'groups',
    switch : {
        ids : ['b48a0a1cd978_0', 'b48a0a1cd978_1'],
        command : { on : false },
    },
    cover : {
        ids : ['a1b2c3d4e5f6_0'],
        command : { position : 'close' },
    },
};

return msg;
